using Ranki.Services.Interfaces;
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Linq;
using System.Security.Claims;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.IdentityModel.Tokens;
using Ranki.Data;
using Ranki.DTOs.Auth;
using Ranki.Models;
using Ranki.Exceptions;
using BCrypt.Net;
namespace Ranki.Services.Implementations { public class AuthService : IAuthService { private readonly AppDbContext _context; private readonly IConfiguration _configuration; public AuthService(AppDbContext context, IConfiguration configuration) { _context = context; _configuration = configuration; } public async Task<AuthResponse> RegisterAsync(RegisterRequest request) { if (await _context.Users.AnyAsync(u => u.Email == request.Email)) { throw new BadRequestException("Email already exists"); } var user = new User { Email = request.Email, FullName = request.FullName, PasswordHash = BCrypt.Net.BCrypt.HashPassword(request.Password), Role = "BusinessOwner" }; _context.Users.Add(user); var activityLog = new ActivityLog { User = user, Action = "Register", Details = $"User registered with email {user.Email}" }; _context.ActivityLogs.Add(activityLog); await _context.SaveChangesAsync(); return await GenerateAuthResponse(user); } public async Task<AuthResponse> LoginAsync(LoginRequest request) { var user = await _context.Users.FirstOrDefaultAsync(u => u.Email == request.Email); if (user == null || !BCrypt.Net.BCrypt.Verify(request.Password, user.PasswordHash)) { throw new UnauthorizedException("Invalid email or password"); } var activityLog = new ActivityLog { UserId = user.Id, Action = "Login", Details = "User logged in successfully" }; _context.ActivityLogs.Add(activityLog); await _context.SaveChangesAsync(); return await GenerateAuthResponse(user); } public async Task<AuthResponse> RefreshTokenAsync(RefreshTokenRequest request) { var user = await _context.Users.FirstOrDefaultAsync(u => u.RefreshToken == request.RefreshToken); if (user == null || user.RefreshTokenExpiry < DateTime.UtcNow) { throw new UnauthorizedException("Invalid or expired refresh token"); } return await GenerateAuthResponse(user); } public async Task<bool> LogoutAsync(RefreshTokenRequest request) { var user = await _context.Users.FirstOrDefaultAsync(u => u.RefreshToken == request.RefreshToken); if (user != null) { user.RefreshToken = null; user.RefreshTokenExpiry = null; var activityLog = new ActivityLog { UserId = user.Id, Action = "Logout", Details = "User logged out" }; _context.ActivityLogs.Add(activityLog); await _context.SaveChangesAsync(); return true; } throw new BadRequestException("Invalid refresh token"); } public async Task<bool> ForgotPasswordAsync(ForgotPasswordRequest request) { var user = await _context.Users.FirstOrDefaultAsync(u => u.Email == request.Email); if (user != null) { var activityLog = new ActivityLog { UserId = user.Id, Action = "ForgotPassword", Details = "Password reset requested" }; _context.ActivityLogs.Add(activityLog); await _context.SaveChangesAsync(); } return true; } public async Task<bool> ResetPasswordAsync(ResetPasswordRequest request) { var user = await _context.Users.FirstOrDefaultAsync(u => u.Email == request.Email); if (user != null) { user.PasswordHash = BCrypt.Net.BCrypt.HashPassword(request.NewPassword); var activityLog = new ActivityLog { UserId = user.Id, Action = "ResetPassword", Details = "Password was reset" }; _context.ActivityLogs.Add(activityLog); await _context.SaveChangesAsync(); return true; } throw new BadRequestException("Invalid request"); } private async Task<AuthResponse> GenerateAuthResponse(User user) { var tokenHandler = new JwtSecurityTokenHandler(); var jwtKey = _configuration["Jwt:Key"]; if (string.IsNullOrEmpty(jwtKey)) throw new Exception("JWT Key is missing"); var key = Encoding.ASCII.GetBytes(jwtKey); var tokenDescriptor = new SecurityTokenDescriptor { Subject = new ClaimsIdentity(new[] { new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()), new Claim(ClaimTypes.Email, user.Email), new Claim(ClaimTypes.Role, user.Role) }), Expires = DateTime.UtcNow.AddMinutes(15), Issuer = _configuration["Jwt:Issuer"], Audience = _configuration["Jwt:Audience"], SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256Signature) }; var token = tokenHandler.CreateToken(tokenDescriptor); var jwtToken = tokenHandler.WriteToken(token); var refreshToken = GenerateRefreshToken(); user.RefreshToken = refreshToken; user.RefreshTokenExpiry = DateTime.UtcNow.AddDays(7); _context.Users.Update(user); await _context.SaveChangesAsync(); return new AuthResponse { AccessToken = jwtToken, RefreshToken = refreshToken, Role = user.Role, Message = "Success" }; } private string GenerateRefreshToken() { var randomNumber = new byte[32]; using var rng = RandomNumberGenerator.Create(); rng.GetBytes(randomNumber); return Convert.ToBase64String(randomNumber); } } }
